111	export const NEVER_ALLOWED_NAME_PATTERNS = [
112	  /TOKEN/i,
113	  /SECRET/i,
114	  /PASSWORD/i,
115	  /PASSWD/i,
116	  /KEY/i,
117	  /AUTH/i,
