7	import fs from 'node:fs';
8	import os from 'node:os';
9	import path from 'node:path';
10	import {
11	  BASE_SEATBELT_PROFILE,
12	  NETWORK_SEATBELT_PROFILE,
13	} from './baseProfile.js';
14	
15	/**
16	 * Options for building macOS Seatbelt arguments.
17	 */
18	export interface SeatbeltArgsOptions {
19	  /** The primary workspace path to allow access to. */
20	  workspace: string;
21	  /** Additional paths to allow access to. */
22	  allowedPaths?: string[];
23	  /** Whether to allow network access. */
24	  networkAccess?: boolean;
25	}
26	
27	/**
28	 * Resolves symlinks for a given path to prevent sandbox escapes.
29	 * If a file does not exist (ENOENT), it recursively resolves the parent directory.
30	 * Other errors (e.g. EACCES) are re-thrown.
31	 */
32	function tryRealpath(p: string): string {
33	  try {
34	    return fs.realpathSync(p);
35	  } catch (e) {
36	    if (e instanceof Error && 'code' in e && e.code === 'ENOENT') {
37	      const parentDir = path.dirname(p);
38	      if (parentDir === p) {
39	        return p;
40	      }
41	      return path.join(tryRealpath(parentDir), path.basename(p));
42	    }
43	    throw e;
44	  }
45	}
46	
47	/**
48	 * Builds the arguments array for sandbox-exec using a strict allowlist profile.
49	 * It relies on parameters passed to sandbox-exec via the -D flag to avoid
50	 * string interpolation vulnerabilities, and normalizes paths against symlink escapes.
51	 *
52	 * Returns arguments up to the end of sandbox-exec configuration (e.g. ['-p', '<profile>', '-D', ...])
53	 * Does not include the final '--' separator or the command to run.
54	 */
55	export function buildSeatbeltArgs(options: SeatbeltArgsOptions): string[] {
56	  let profile = BASE_SEATBELT_PROFILE + '\n';
57	  const args: string[] = [];
58	
59	  const workspacePath = tryRealpath(options.workspace);
60	  args.push('-D', `WORKSPACE=${workspacePath}`);
61	
62	  const tmpPath = tryRealpath(os.tmpdir());
63	  args.push('-D', `TMPDIR=${tmpPath}`);
64	
65	  if (options.allowedPaths) {
66	    for (let i = 0; i < options.allowedPaths.length; i++) {
67	      const allowedPath = tryRealpath(options.allowedPaths[i]);
68	      args.push('-D', `ALLOWED_PATH_${i}=${allowedPath}`);
69	      profile += `(allow file-read* file-write* (subpath (param "ALLOWED_PATH_${i}")))\n`;
70	    }
71	  }
72	
73	  if (options.networkAccess) {
74	    profile += NETWORK_SEATBELT_PROFILE;
75	  }
76	
77	  args.unshift('-p', profile);
78	
79	  return args;
80	}
