14	 * A FileSystemService implementation that performs operations through a sandbox.
15	 */
16	export class SandboxedFileSystemService implements FileSystemService {
17	  constructor(
18	    private sandboxManager: SandboxManager,
19	    private cwd: string,
20	  ) {}
21	
22	  async readTextFile(filePath: string): Promise<string> {
23	    const prepared = await this.sandboxManager.prepareCommand({
24	      command: '__read',
25	      args: [filePath],
26	      cwd: this.cwd,
27	      env: process.env,
28	    });
29	
30	    return new Promise((resolve, reject) => {
31	      // Direct spawn is necessary here for streaming large file contents.
32	
33	      const child = spawn(prepared.program, prepared.args, {
34	        cwd: this.cwd,
35	        env: prepared.env,
36	      });
37	
38	      let output = '';
39	      let error = '';
40	
41	      child.stdout?.on('data', (data) => {
42	        output += data.toString();
43	      });
44	
45	      child.stderr?.on('data', (data) => {
46	        error += data.toString();
47	      });
48	
49	      child.on('close', (code) => {
50	        if (code === 0) {
51	          resolve(output);
52	        } else {
53	          reject(
54	            new Error(
55	              `Sandbox Error: read_file failed for '${filePath}'. Exit code ${code}. ${error ? 'Details: ' + error : ''}`,
56	            ),
57	          );
58	        }
59	      });
60	
61	      child.on('error', (err) => {
62	        reject(
63	          new Error(
64	            `Sandbox Error: Failed to spawn read_file for '${filePath}': ${err.message}`,
65	          ),
66	        );
67	      });
68	    });
69	  }
