71	  async writeTextFile(filePath: string, content: string): Promise<void> {
72	    const prepared = await this.sandboxManager.prepareCommand({
73	      command: '__write',
74	      args: [filePath],
75	      cwd: this.cwd,
76	      env: process.env,
77	    });
78	
79	    return new Promise((resolve, reject) => {
80	      // Direct spawn is necessary here for streaming large file contents.
81	
82	      const child = spawn(prepared.program, prepared.args, {
83	        cwd: this.cwd,
84	        env: prepared.env,
85	      });
86	
87	      child.stdin?.on('error', (err) => {
88	        // Silently ignore EPIPE errors on stdin, they will be caught by the process error/close listeners
89	        if (isNodeError(err) && err.code === 'EPIPE') {
90	          return;
91	        }
92	        debugLogger.error(
93	          `Sandbox Error: stdin error for '${filePath}': ${
94	            err instanceof Error ? err.message : String(err)
95	          }`,
96	        );
97	      });
98	
99	      child.stdin?.write(content);
100	      child.stdin?.end();
101	
102	      let error = '';
103	      child.stderr?.on('data', (data) => {
104	        error += data.toString();
105	      });
106	
107	      child.on('close', (code) => {
108	        if (code === 0) {
109	          resolve();
110	        } else {
111	          reject(
112	            new Error(
113	              `Sandbox Error: write_file failed for '${filePath}'. Exit code ${code}. ${error ? 'Details: ' + error : ''}`,
114	            ),
115	          );
116	        }
117	      });
118	
